def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    divider = next(r for r, row in enumerate(grid) if all(v == 2 for v in row))
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w)
             if grid[r][c] not in (2, background)]
    if not cells:
        return out

    if min(r for r, c, v in cells) > divider:
        direction = 1
        delta = divider + 1 - min(r for r, c, v in cells)
        moved_rows = [r + delta for r, c, v in cells]
        stripe = max(moved_rows) + 1
    else:
        direction = -1
        delta = divider - 1 - max(r for r, c, v in cells)
        moved_rows = [r + delta for r, c, v in cells]
        stripe = min(moved_rows) - 1

    for r, c, v in cells:
        out[r][c] = background
    for (r, c, v), nr in zip(cells, moved_rows):
        out[nr][c] = v

    if 0 <= stripe < h:
        out[stripe] = [8] * w
    return out
